// Last 7 days: totals by category, taxes paid, biggest purchases.
const WEEKLY_BUDGET = Math.round(600 / 4.33);
const since = new Date(Date.now() - 7 * 864e5).toISOString().slice(0, 10);
const rows = $input.all().map(i => i.json).filter(r => String(r['Date'] || '') >= since);
const by = {}, owed = {};
let total = 0, tax = 0, keep = 0;
for (const r of rows) {
  const t = Number(r['Your share'] !== '' && r['Your share'] !== undefined ? r['Your share'] : r['Total']) || 0;
  total += t; tax += (Number(r['GST']) || 0) + (Number(r['PST']) || 0) + (Number(r['HST']) || 0);
  by[r['Category']] = (by[r['Category']] || 0) + t;
  if (r['Keep for taxes']) keep++;
  for (const n of String(r['Split with'] || '').split(',').map(s => s.trim()).filter(Boolean))
    owed[n] = (owed[n] || 0) + (Number(r['Each owes you']) || 0);
}
const owedText = Object.entries(owed).map(([n, v]) => `${n} owes you $${v.toFixed(2)}`).join('; ') || 'Nobody owes you anything';
const cats = Object.entries(by).sort((a, b) => b[1] - a[1]).map(([c, v]) => `${c}: $${v.toFixed(2)}`);
const top = rows.sort((a, b) => (Number(b['Total']) || 0) - (Number(a['Total']) || 0)).slice(0, 3)
  .map(r => `${r['Vendor']} $${Number(r['Total']).toFixed(2)} (${r['Category']})`);
return [{ json: { since, receipts: rows.length, total: total.toFixed(2), tax: tax.toFixed(2),
  weekly_budget: WEEKLY_BUDGET, over: total > WEEKLY_BUDGET, by_category: cats.join('\n'), top: top.join('\n'),
  owed: owedText, keep } }];
